(function () {
  'use strict';
  // Present value: what future money is worth today at a chosen discount rate.
  //   i = rate per payment period = (1 + r/m)^(m/p) - 1 (e^(r/p) - 1 for continuous compounding)
  //   PV of lump sum = FV / (1 + i)^n
  //   PV of payments = PMT x [1 - (1 + i)^-n] / i, times (1 + i) when paid at the start of each period
  // Checked in Node (pv.test.js): $10,000 in 10 years at 5% yearly = $6,139.13; $1,000 a year for
  // 10 years at 5% = $7,721.73 (end) and $8,107.82 (start), matching standard PV-of-annuity tables
  // (factor 7.7217); $100/month for 30 years at 6% monthly = $16,679.16; 0% rate = plain sum;
  // continuous 6% on $1,000 over 10 years = 1000e^-0.6 = $548.81; the year-by-year rows add up to
  // the closed-form total.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });

  // --- calc start
  function periodRate(annualRate, compPerYear, perYear) {
    if (compPerYear === 0) return Math.exp(annualRate / perYear) - 1;
    return Math.pow(1 + annualRate / compPerYear, compPerYear / perYear) - 1;
  }

  // p: fv, pmt, rate (decimal), years, freq (payments a year), comp (0 = continuous), due (bool)
  function presentValue(p) {
    var i = periodRate(p.rate, p.comp, p.freq);
    var n = Math.max(1, Math.round(p.years * p.freq));
    var factor = Math.pow(1 + i, -n);
    var annuity = i === 0 ? n : (1 - factor) / i;
    if (p.due) annuity *= 1 + i;
    var lump = p.fv * factor, payments = p.pmt * annuity;
    var rows = [], yGot = 0, yPv = 0, run = 0;
    for (var k = 1; k <= n; k++) {
      var t = p.due ? k - 1 : k;           // when this period's payment arrives, in periods
      var pv = p.pmt * Math.pow(1 + i, -t);
      yGot += p.pmt; yPv += pv;
      if (k === n) { yGot += p.fv; yPv += lump; }
      if (k % p.freq === 0 || k === n) {
        run += yPv;
        rows.push({ year: k / p.freq, received: yGot, worth: yPv, total: run });
        yGot = 0; yPv = 0;
      }
    }
    return { pv: lump + payments, lump: lump, payments: payments, nominal: p.fv + p.pmt * n, n: n, factor: factor, rows: rows };
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function update() {
    var fv = num('pvFuture'), pmt = num('pvPayment'), rate = num('pvRate'), years = num('pvYears');
    var freq = parseInt(document.getElementById('pvFreq').value, 10);
    var compVal = document.getElementById('pvComp').value;
    var comp = compVal === 'same' ? freq : parseInt(compVal, 10);
    var due = document.getElementById('pvTiming').value === 'begin';
    var error = document.getElementById('pvError');
    var bad = [fv, pmt, rate, years].some(isNaN) || fv < 0 || pmt < 0 || fv + pmt <= 0 || rate < 0 ||
              rate > 100 || years <= 0 || years > 100 || Math.round(years * freq) < 1;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a lump sum or a payment (not negative), a rate from 0 to 100%, and at least one payment period up to 100 years.';
      return;
    }
    var r = presentValue({ fv: fv, pmt: pmt, rate: rate / 100, years: years, freq: freq, comp: comp, due: due });
    document.getElementById('pvTotal').textContent = money.format(r.pv);
    document.getElementById('pvNominal').textContent = money.format(r.nominal);
    document.getElementById('pvDiscount').textContent = money.format(r.nominal - r.pv);
    document.getElementById('pvLump').textContent = money.format(r.lump);
    document.getElementById('pvPayments').textContent = money.format(r.payments);
    document.getElementById('pvCount').textContent = whole.format(pmt > 0 ? r.n : 0);
    document.getElementById('pvFactor').textContent = '$' + r.factor.toFixed(4);
    document.getElementById('pvSchedule').innerHTML = r.rows.map(function (row) {
      var label = Math.abs(row.year - Math.round(row.year)) < 1e-9 ? String(Math.round(row.year)) : Math.ceil(row.year) + ' (part)';
      return '<tr><td>' + label + '</td><td>' + money.format(row.received) + '</td><td>' +
             money.format(row.worth) + '</td><td>' + money.format(row.total) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('pvForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
